newcode='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx))
                        stack.append((yy,xx))
            comps.append((color, cells))

    def bounds(cells):
        return (min(r for r,c in cells), max(r for r,c in cells),
                min(c for r,c in cells), max(c for r,c in cells))

    def is_l(cells):
        r0, r1, c0, c1 = bounds(cells)
        points = set(cells)
        for rr in (r0, r1):
            for cc in (c0, c1):
                leg = {(rr,c) for c in range(c0,c1+1)} | {(r,cc) for r in range(r0,r1+1)}
                if points == leg:
                    return True
        return False

    # The key is the largest component that forms a solid right-angle L.
    key_color, key_cells = max((item for item in comps if is_l(item[1])),
                               key=lambda item: len(item[1]))
    kr0, kr1, kc0, kc1 = bounds(key_cells)
    def shape(cells):
        r0, r1, c0, c1 = bounds(cells)
        return frozenset((r-r0, c-c0) for r,c in cells)

    # A separate component inside the L's bounding box is the shape sample.
    samples = [(color, cells) for color, cells in comps
               if cells is not key_cells and all(kr0 <= r <= kr1 and kc0 <= c <= kc1
                                                 for r,c in cells)]
    if not samples:
        return [row[:] for row in grid]
    sample_shape = shape(samples[0][1])
    out = [row[:] for row in grid]
    for color, cells in comps:
        if cells is key_cells:
            continue
        r0, r1, c0, c1 = bounds(cells)
        outside_key_box = r1 < kr0 or r0 > kr1 or c1 < kc0 or c0 > kc1
        if outside_key_box and shape(cells) == sample_shape:
            for r, c in cells:
                out[r][c] = key_color
    return out
'''
